import{_ as i,l as d,o as e,c as s,v as t,p as l,x as o,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"反射与元数据","description":"","frontmatter":{"title":"反射与元数据","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reflection-metadata.md","filePath":"cs/reflection-metadata.md","lastUpdated":1789023840000}'),h={name:"cs/reflection-metadata.md"};function m(_,a,f,E,u,T){const r=d("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="反射与元数据" tabindex="-1">反射与元数据 <a class="header-anchor" href="#反射与元数据" aria-label="Permalink to &quot;反射与元数据&quot;">​</a></h1><div class="epigraph"><p>运行时描述类型、方法与字段：名字、签名、注解。反射按名调用，牺牲静态检查与内联，换工具与框架的灵活性。</p><footer>—— 据 Java 虚拟机规范属性与反射 API；CLI 元数据；对照[DWARF](/cs/dwarf-debug-info) 整理</footer></div><p>上一课<a href="/cs/vtable-dispatch">虚表</a> 按槽调用，槽在编译期已知。缺口是<strong>按字符串</strong>：<code>getMethod(&quot;foo&quot;)</code>。元数据表（JVM、.NET）或 RTTI（C++）。本课钉代价，内存模型下一课。不把 Java 注解处理器当全部。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>调试 DWARF 给工具看；反射给程序看。实现：类文件里的常量池与属性。调用：查找、权限、装箱参数、不能内联。缺口是<strong>这条慢路径与安全</strong>（可访问性），不是 vptr 布局。</p><p>擦除泛型：反射看见的是 raw，接<a href="/cs/generics-monomorphization">泛型</a>。</p><h3 id="反射不是宏" tabindex="-1">反射不是宏 <a class="header-anchor" href="#反射不是宏" aria-label="Permalink to &quot;反射不是宏&quot;">​</a></h3><p>宏在编译期改树；反射在运行期查表。卫生无关。不要混。</p><p><span class="marginnote">JVM 规范。CLI。C++ RTTI/<code>typeid</code>。本课不写 JNI 全部。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加载类时解析元数据。API：列举方法、读注解、<code>invoke</code>。JIT：对稳定反射调用可降成直调（推测+去优化）。关闭：strip 元数据则反射失败，体积减。</p>',11)),(e(),l(p,null,{default:o(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20META%5B%22%E7%B1%BB%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20LOOK%5B%22%E6%8C%89%E5%90%8D%E6%9F%A5%E6%89%BE%22%5D%0A%20%20LOOK%20--%3E%20INV%5B%22%E8%A3%85%E7%AE%B1%20%2F%20%E8%B0%83%E7%94%A8%22%5D%0A%20%20INV%20--%3E%20JIT%5B%22%E5%8F%AF%E9%80%89%E6%8E%A8%E6%B5%8B%E7%9B%B4%E8%B0%83%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/symbol-interposition">符号插入</a>：<code>dlsym</code> 是 C 的反射亲戚。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>安全：模块系统限制深反射。性能：第一次查找贵，缓存 Method 对象。不要在热循环 <code>getMethod</code>。GC：元数据是根（类对象长命）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写内存模型。后课默认：按名调用走元数据。下一课语言内存模型与 data race。</p><p>也不把反射当光学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>反射：运行时元数据 + 按名调用。</li><li>与 vtable 槽调用、与宏阶段都不同。</li><li>可被 JIT 推测；可被 strip。</li><li>出处：JVM 规范；CLI；对照 DWARF、Itanium RTTI。</li></ul>',8))])}const B=i(h,[["render",m]]);export{b as __pageData,B as default};
